namespace DssHarness.Core.Codebase.Languages;

/// <summary>
/// Python, through the structural scanner C, C++ and Dart are read by, with Python's lexical rules and declarations: its
/// module a namespace named by its dotted path; every class, function, method, constructor and assigned name with its lines,
/// signature and summary; its imports, a bare one bound to files by the package layout and its roots, each name bound for
/// the code of the declaration it is imported in; base lists; each call with what its receiver is where the file says; each
/// type an annotation names; and a test file's tests and fixtures.
/// </summary>
public sealed class PythonExtractor : ICodeGraphExtractor
{
    /// <inheritdoc/>
    public string Language => "python";

    /// <inheritdoc/>
    public int Version => 1;

    /// <inheritdoc/>
    public CodeGraphClaims Claims { get; } = CodeGraphClaims.OfExtensions(".py", ".pyi", ".pyw");

    /// <inheritdoc/>
    public bool Outlines => false;

    /// <inheritdoc/>
    public CodeGraphExtractorHelp Help { get; } = new(
        "Python (.py, .pyi and .pyw), through the structural scanner C, C++ and Dart are read by: the module a namespace named by its path in dots, an __init__.py its directory's package, every name it declares reachable by an importer, and its own imported names with them, as a package re-exports what it imports; every class, function, method, constructor and assigned name - a module-level or class-level name in capitals a constant, any other a field, each name of a target list (a, *b = ...) one of its own, an attribute a method first assigns through self or cls a field of its class - and each type alias (type X = ...) a type, with its signature, summary and body, nested classes and functions kept inside the node that holds them, a type parameter (def f[T], class C[T: Base]) its declaration's own; a function's body a scope of its own, whose names are looked up in it, then in the functions around it and the module, never in a class around it, as Python looks them up, and what its head runs - its decorators, annotations and defaults - looked up where the function is defined; async for, async with and match with its case clauses read as the compound statements they are, match, case and type soft keywords a name may be; imports - import a.b.c binding a, the package a, and reaching the module a.b.c by the dotted names to it, a step between them a module of its own where the code reaches it; a bare module looked for by the package layout, from the directory above the file's package and then each directory above it to the tree's root, as a package's __init__.py or the module's .py - a file in a directory that is no package taking its own directory's module and the one above it as candidates, since it is a script's and a namespace package's alike - and then under each root of the layout, the directory an outermost package stands in, src/ among them, and each a pyproject.toml or a setup.cfg declares; from a.b import c, d as e showing each name and binding it - c a module of its own where one stands so and else the name a.b binds, so c.f() reaches f in either; a relative one a path beside the file; from m import * the names m publishes - its __all__'s where it is a list or a tuple of string literals the code leaves alone, else the names not written with a leading underscore, what its own * imports take among them; an import at the module's top - in its conditional blocks too - binding names of the module, its importers's too, and one in a function or a class binding for that declaration's own code alone; base lists, the first base inherits and the others mixesIn, the types a base's subscript names references, and a method that has the name of one its bases declare an overrides edge; each call with what its receiver is where the file says - self and cls the type's own, super() its base's, a name an import binds what the import reaches - a module path however long, a module's or a class's member - the head and each member of a chain on its way a use, and a call of a capitalized name an instantiates of the class it names, as a method's cls(...) and type(self)(...) are of the class the method is of; each type an annotation, a return annotation, a string annotation, an isinstance, an issubclass, an except or a case's class pattern names, dotted or not, through the imports the file makes - Literal's values and Annotated's metadata read as code; a case's dotted values uses and its captures bound; each attribute and each name a body reads without calling it and does not bind itself - a local, a parameter, a lambda's parameter, a comprehension's target and a name a function around it binds its own, nearer than an import or a builtin of the name, a name a class's own code reads that the class declares the class's, a builtin the file declares or imports the file's; each decorator's expression whole, the language's own and a framework's decorators kept as modifiers by their dotted name, what they are given code; each string literal the file holds - a triple-quoted one's and a raw one's too, an f-string's and a t-string's constant parts each one of its own - a debugging field's text to its = among them, as written - its fields and the fields its formats hold read as code, an __all__'s entries among them - by its value as Python reads its escapes - a character's name, \\N{...}, kept as written - a bytes one's as bytes and a formatted one's doubled braces a brace, its line and the node it is written in; and a test file's test* functions, Test* classes, TestCase subclasses and their test* methods as tests, a class of a test file built on a base another file declares a test class where the link finds that base one, each parameter a test or a fixture requires a reference to the fixture that provides it, as pytest finds one - the test's own class's or module's, else the conftest.py's of its directory or of the nearest one above it that declares it - a function pytest's @fixture decorates",
        [
            // What a file shows of a limit is said by sites of that file: each sign a mark's kind (<see cref="PythonReading"/>) or candidates.
            new CodeGraphLimit("computed-attributes", "computed attribute access: getattr, setattr, delattr and hasattr reach a member by a name the code computes - marked dynamic, no edge") { Signs = [PythonReading.ComputedAttribute] },
            new CodeGraphLimit("dynamic-imports", "dynamic imports: importlib.import_module and __import__ name a module by a computed name - marked dynamic") { Signs = [PythonReading.DynamicImport] },
            new CodeGraphLimit("unseen-roots", "a root of the path the tree does not show: a bare import is looked for from the directory above the file's package, each directory above it to the tree's root, and the roots of the layout - the directory each outermost package stands in, and each a pyproject.toml or a setup.cfg names in its own words - so a module a project installs from outside the tree, or finds by a PYTHONPATH, a .pth file, a sys.path the code changes or a root a project file computes, binds nothing, and what the file reaches through it is counted external") { Signs = [CodeGraphLimit.External] },
            ("monkey-patching", "monkey-patching and decorators that rewrite what they wrap, metaclass effects, and code generated at build time: not read"),
            new CodeGraphLimit("exec-eval", "exec and eval: code a string holds - marked dynamic, and not linked") { Signs = [PythonReading.ComputedCode] },
            new CodeGraphLimit("duck-typing", "a duck-typed receiver: a call on a parameter, a local or a value the file does not type is bound by its name alone, at candidates where several declarations share it - a member of an annotated parameter's type to each override of it; a call through a value a body binds - a parameter, a local given a function - is marked dynamic and not linked") { Signs = [CodeGraphLimit.Candidates, PythonReading.FunctionValue] },
            ("capital-functions", "a function written with a capital first letter: a call of its name is read as making a class of that name, never as calling the function"),
            new CodeGraphLimit("computed-all", "a module's __all__ the code computes or changes after assigning it a list - __all__ = [...] + more, __all__.append - which is not read, the file marked dynamic, so from m import * binds the names not written with a leading underscore") { Signs = [PythonReading.ComputedExports] },
            new CodeGraphLimit("unclosed", "a bracket or a string that never closes, which Python refuses and a file being edited may hold: what follows it is read as held in the bracket - to the end of the file where no group around it closes - or as the string's text - to its line's end, or the file's for three quotes - and no statement it takes in as one of its own; marked dynamic") { Signs = [PythonReading.Unclosed] },
            ("module-getattr", "names a module makes by a __getattr__ of its own or by assigning to globals(): not reached through it by its importers; a name it imports under another name is reached through it by that name alone"),
            new CodeGraphLimit("unbound-names", "a name a file neither declares nor imports: it binds nothing, the repository's declarations not being looked through for it, so a class named in a base list without being imported makes no edge, and the reference is counted external") { Signs = [CodeGraphLimit.External] },
            new CodeGraphLimit("outside-fixtures", "a fixture no conftest.py of the test's directory or of one above it declares - pytest's own, an installed plugin's, one a module pytest_plugins names: a parameter naming one binds nothing, and is counted external; a fixture usefixtures names or one used as autouse is no parameter, and is no reference") { Signs = [CodeGraphLimit.External] },
            ("lambdas", "lambdas, comprehensions and conditional expressions as nodes of their own: what they call is the calls of the declaration they are written in, the names they bind theirs while they are read"),
            ("test-helpers", "a test written through a helper of its own, and not a test* function of a test file or a test* method of a Test* class, a TestCase subclass or a class built on one any number of bases up, as a test"),
            ("lowercase-annotations", "a type an annotation names whose last name is written in lower case - np.ndarray, a dotted name - where it is not one name the file declares or imports: it names nothing; a subscript's own name - Union, Optional - is a reference like the types it is given; a type the code builds at run time names nothing"),
            ("outside-attributes", "an attribute assigned outside its class's methods - obj.x = 1 elsewhere, setattr - or through a receiver of another name than self or cls, as a field of the class: not declared"),
            ("manifests", "requirements.txt and a lock file: listed only; and of a pyproject.toml and a setup.cfg the roots of the layout alone, which the pyproject extractor reads - a project's dependencies, its build backend and its tools' configuration are not in the graph"),
        ])
    {
        Holds = "its tokens, read by position and never one string of the file: a name, a number, a punctuator and a string each by where it begins and ends, a string's value decoded from its pieces, an f-string's fields scanned as texts of their own where they stand",
    };

    /// <inheritdoc/>
    public FileExtract Extract(CodeFileInput input)
    {
        ArgumentNullException.ThrowIfNull(input);
        return new PythonReading(Language, input.Path, input.Text).Read();
    }
}
